using knkwebapi_v2.Properties;
using knkwebapi_v2.Services.Interfaces;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;

namespace knkwebapi_v2.Models;

/// <summary>
/// An additive, create-only seed of the Knights and Kings v1 item catalog, ported from
/// <c>docs/specs/items/V1_SEED_DATA.md</c>. v1's own item table (<c>Products</c>) no longer exists,
/// so the rows below were recovered from v1 players' inventories and ender chests (Old_KnK
/// playerdata) and generated by <c>knk-workspace/scripts/v1-item-port/v1_items.py generate</c> -
/// regenerate rather than hand-edit the <see cref="Blueprints"/> table.
/// <para>
/// Same convention as <see cref="KitSeed"/>: every row is looked up by its natural key
/// (<c>Name</c>, <c>Stars</c> for <see cref="Grade"/>, <c>Key</c> for
/// <see cref="EnchantmentDefinition"/>, <c>NamespaceKey</c> for the Minecraft refs) and reused if
/// it already exists - never updated, diffed or upserted. Join rows (default enchantments, the
/// <see cref="LegacyTag"/> tag) are only added under a blueprint this run itself created, so an
/// existing "Iron Sword"/"Arrow" (KitSeed's) is left exactly as it is.
/// </para>
/// <para>
/// Enchantment keys are either <c>minecraft:*</c> (vanilla; v1's numeric ids mapped to modern
/// keys, created on demand with a catalog-backed <see cref="MinecraftEnchantmentRef"/>) or one of
/// knk-plugin's 12 custom enchantment ids (v1 lore lines such as "§7blindness III"), which
/// <see cref="AbilityDefinition.SeedCanonicalAsync"/> owns - a custom key it hasn't created is
/// logged and skipped, never invented here. Levels are v1's, including vanilla levels above the
/// vanilla cap (the plugin applies vanilla enchantments unsafely).
/// </para>
/// </summary>
public static class ItemBlueprintV1Seed
{
