    public static async Task SeedCanonicalAsync(
        KnKDbContext context,
        IMinecraftMaterialCatalogService? materialCatalog = null,
        IMinecraftEnchantmentCatalogService? enchantmentCatalog = null,
        ILogger? logger = null,
        CancellationToken cancellationToken = default)
    {
        var created = new Dictionary<string, int>();
        void Count(string what) => created[what] = created.GetValueOrDefault(what) + 1;

        // --- MinecraftMaterialRef (icons) ---
        var iconKeys = Categories.Select(c => c.IconKey)
            .Concat(Blueprints.Select(b => b.IconKey))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();
        var materials = ByKey(
            await context.MinecraftMaterialRefs.Where(m => iconKeys.Contains(m.NamespaceKey)).ToListAsync(cancellationToken),
            m => m.NamespaceKey, m => m.Id);
        var materialCatalogByKey = materialCatalog?.GetAll()
            .GroupBy(e => e.NamespaceKey, StringComparer.OrdinalIgnoreCase)
            .ToDictionary(g => g.Key, g => g.First(), StringComparer.OrdinalIgnoreCase)
            ?? new Dictionary<string, MinecraftMaterialCatalogEntry>(StringComparer.OrdinalIgnoreCase);
        foreach (var key in iconKeys)
        {
            if (materials.ContainsKey(key)) continue;
            materialCatalogByKey.TryGetValue(key, out var entry);
            var material = new MinecraftMaterialRef
            {
                NamespaceKey = key,
                Category = entry?.Category ?? FallbackMaterialCategory,
                LegacyName = entry?.LegacyName,
                IconUrl = entry?.IconUrl,
            };
            context.MinecraftMaterialRefs.Add(material);
            materials[key] = material;
            Count(nameof(MinecraftMaterialRef));
        }

        // --- Tag ---
        var tags = ByKey(await context.Tags.ToListAsync(cancellationToken), t => t.Name, t => t.Id);
        if (!tags.TryGetValue(LegacyTag, out var legacyTag))
        {
            legacyTag = new Tag { Name = LegacyTag };
            context.Tags.Add(legacyTag);
            Count(nameof(Tag));
        }

        // --- Category ---
        var categories = ByKey(await context.Categories.ToListAsync(cancellationToken), c => c.Name, c => c.Id);
        foreach (var (name, iconKey) in Categories)
        {
            if (categories.ContainsKey(name)) continue;
            var category = new Category { Name = name, IconMaterialRef = materials[iconKey] };
            context.Categories.Add(category);
            categories[name] = category;
            Count(nameof(Category));
        }

        // --- Grade (by star count: that's what v1 stored) ---
        var grades = (await context.Grades.ToListAsync(cancellationToken))
            .GroupBy(g => g.Stars)
            .ToDictionary(g => g.Key, g => g.OrderBy(x => x.Id).First());
        foreach (var (name, stars) in Grades)
        {
            if (grades.ContainsKey(stars)) continue;
            var grade = new Grade { Name = name, Stars = stars };
            context.Grades.Add(grade);
            grades[stars] = grade;
            Count(nameof(Grade));
        }

        // --- EnchantmentDefinition (+ MinecraftEnchantmentRef for new vanilla ones) ---
        var enchantments = ByKey(await context.EnchantmentDefinitions.ToListAsync(cancellationToken), e => NormalizeEnchantmentKey(e.Key), e => e.Id);
        var enchantmentRefs = ByKey(await context.MinecraftEnchantmentRefs.ToListAsync(cancellationToken), r => r.NamespaceKey, r => r.Id);
        var missingCustom = new SortedSet<string>(StringComparer.Ordinal);
        foreach (var key in Blueprints.SelectMany(b => b.Enchantments).Select(e => e.Key).Distinct(StringComparer.OrdinalIgnoreCase))
        {
            if (enchantments.ContainsKey(NormalizeEnchantmentKey(key))) continue;
            if (!key.StartsWith("minecraft:", StringComparison.OrdinalIgnoreCase))
            {
                missingCustom.Add(key);
                continue;
            }

            var catalogEntry = enchantmentCatalog?.GetByNamespaceKey(key);
            if (!enchantmentRefs.TryGetValue(key, out var enchantmentRef))
            {
                enchantmentRef = new MinecraftEnchantmentRef
                {
                    NamespaceKey = key,
                    LegacyName = catalogEntry?.LegacyName,
                    Category = catalogEntry?.Category,
                    IconUrl = catalogEntry?.IconUrl,
                    MaxLevel = catalogEntry?.MaxLevel ?? 1,
                    DisplayName = catalogEntry?.DisplayName ?? ToDisplayName(key),
                    IsCustom = false,
                };
                context.MinecraftEnchantmentRefs.Add(enchantmentRef);
                enchantmentRefs[key] = enchantmentRef;
                Count(nameof(MinecraftEnchantmentRef));
            }

            var definition = new EnchantmentDefinition
            {
                Key = key,
                DisplayName = catalogEntry?.DisplayName ?? ToDisplayName(key),
                Description = string.Empty,
                IsCustom = false,
                MaxLevel = catalogEntry?.MaxLevel ?? 1,
                BaseEnchantmentRef = enchantmentRef,
            };
            context.EnchantmentDefinitions.Add(definition);
            enchantments[NormalizeEnchantmentKey(key)] = definition;
            Count(nameof(EnchantmentDefinition));
        }

        if (missingCustom.Count > 0)
        {
            logger?.LogWarning(
                "ItemBlueprintV1Seed: custom enchantment definitions not found (seeded by AbilityDefinition.SeedCanonicalAsync); skipping them on new blueprints: {Keys}",
                string.Join(", ", missingCustom));
        }

        // --- ItemBlueprint (+ default enchantments and legacy tag for newly created blueprints only) ---
        // Prices, origins and descriptions are deliberately left unset: v1 playerdata doesn't carry them.
        var blueprints = ByKey(await context.ItemBlueprints.ToListAsync(cancellationToken), b => b.Name, b => b.Id);
        var reused = new List<string>();
        foreach (var spec in Blueprints)
        {
            if (blueprints.ContainsKey(spec.Name))
            {
                reused.Add(spec.Name);
                continue;
            }

            var blueprint = new ItemBlueprint
            {
                Name = spec.Name,
                DefaultDisplayName = spec.DisplayName,
                IconMaterial = materials[spec.IconKey],
                Category = categories[spec.Category],
                Grade = spec.Stars is int stars ? grades[stars] : null,
                DefaultQuantity = 1,
                MaxStackSize = spec.MaxStackSize,
            };
            blueprint.Tags.Add(new ItemBlueprintTag { ItemBlueprint = blueprint, Tag = legacyTag });
            Count(nameof(ItemBlueprintTag));
            foreach (var (key, level) in spec.Enchantments)
            {
                if (!enchantments.TryGetValue(NormalizeEnchantmentKey(key), out var definition)) continue;
                blueprint.DefaultEnchantments.Add(new ItemBlueprintDefaultEnchantment
                {
                    ItemBlueprint = blueprint,
                    EnchantmentDefinition = definition,
                    Level = level,
                });
                Count(nameof(ItemBlueprintDefaultEnchantment));
            }
            context.ItemBlueprints.Add(blueprint);
            blueprints[spec.Name] = blueprint;
            Count(nameof(ItemBlueprint));
        }

        if (created.Count > 0)
        {
            await context.SaveChangesAsync(cancellationToken);
        }

        logger?.LogInformation(
            "ItemBlueprintV1Seed complete. Created: {Created}. Existing blueprints left as-is: {Reused}",
            created.Count == 0 ? "nothing" : string.Join(", ", created.Select(kv => $"{kv.Value} {kv.Key}")),
            reused.Count == 0 ? "none" : string.Join(", ", reused));
    }

    // Vanilla keys match as-is ("minecraft:sharpness"); custom keys match the way the plugin's
    // EnchantmentDefinitionBukkitMapper resolves them ("blindness", "knk:blindness" and
    // "Blindness" are the same enchantment).
    private static string NormalizeEnchantmentKey(string key)
    {
        var trimmed = key.Trim().ToLowerInvariant();
        if (trimmed.StartsWith("minecraft:", StringComparison.Ordinal)) return trimmed;
        var colon = trimmed.IndexOf(':');
        if (colon >= 0) trimmed = trimmed[(colon + 1)..];
        return trimmed.Replace('-', '_').Replace(' ', '_');
    }

    private static string ToDisplayName(string namespaceKey)
    {
        var key = namespaceKey[(namespaceKey.IndexOf(':') + 1)..];
        return string.Join(' ', key.Split('_', StringSplitOptions.RemoveEmptyEntries)
            .Select(w => char.ToUpperInvariant(w[0]) + w[1..]));
    }

    // Natural-key lookup: case-insensitive, and if an admin has somehow created two rows with the
    // same key (none of these columns has a unique index), the oldest one wins.
    private static Dictionary<string, T> ByKey<T>(IEnumerable<T> rows, Func<T, string?> key, Func<T, int> id) =>
        rows.Where(r => !string.IsNullOrWhiteSpace(key(r)))
            .GroupBy(r => key(r)!.Trim(), StringComparer.OrdinalIgnoreCase)
            .ToDictionary(g => g.Key, g => g.OrderBy(id).First(), StringComparer.OrdinalIgnoreCase);
}
